       game/stack.cpp \
       game/rewind.cpp \
       player/player.cpp \
       ghost/ghost.cpp \
       ghost/bfs.cpp \
       maze/graph.cpp

OBJS = $(SRCS:.cpp=.o)

$(TARGET): $(OBJS)
	$(CXX) $(CXXFLAGS) -o $(TARGET) $(OBJS)

